QJsonObject payload(const QString& conversation,const QString& request,const companion::TomDraft& d,const companion::TomConfig& config,const QString& model,const QJsonArray& history,const QString& purpose){QJsonObject out{{"request_id",request},{"conversation_id",conversation},{"provider",config.provider},{"model",model},{"max_output_tokens",companion::scenePurpose(purpose)?config.sceneMaxTokens:config.maxOutputTokens},{"question",d.correctedText.isEmpty()?d.question:d.correctedText},{"scope",d.scope},{"context",d.scope=="general"?QJsonValue(QJsonValue::Null):QJsonValue(d.context)},{"history",history},{"consent",true},{"purpose",purpose}};if(companion::automaticPurpose(purpose)){out["illustration_model"]=config.illustrationModel;if(config.mixedReply)out["mixed_reply"]=true;}if(companion::scenePurpose(purpose)&&config.sceneVersion>=4)out["scene_version"]=config.sceneVersion;if(!d.handwritingImage.isEmpty())out["handwriting_image"]=d.handwritingImage;if(!d.pageImage.isEmpty())out["page_image"]=d.pageImage;return out;}
