QString selectedConversation(const std::filesystem::path& root){auto file=root/"tom/runtime.json";if(!std::filesystem::exists(file))return {};struct stat st{};if(lstat(file.c_str(),&st)||!S_ISREG(st.st_mode)||st.st_uid!=getuid()||st.st_nlink!=1||(st.st_mode&0777)!=0600)throw std::runtime_error("Tom selection record unsafe");QJsonParseError error;auto doc=QJsonDocument::fromJson(underlay::readBounded(file,4096),&error);if(error.error!=QJsonParseError::NoError||!doc.isObject())throw std::runtime_error("Tom selection record corrupt");auto envelope=doc.object(),p=envelope["payload"].toObject();if(p["version"].toInt()!=1||envelope["sha256"].toString().toLatin1()!=underlay::digest(json(p)).toHex())throw std::runtime_error("Tom selection record checksum");auto id=p["conversation"].toString();if(!id.isEmpty()&&!uuid(id))throw std::runtime_error("Tom selection record identity");return id;}
void saveSelection(const std::filesystem::path& root,const QString& id){QJsonObject p{{"version",1},{"conversation",id}};underlay::atomicFile(root/"tom/runtime.json",json({{"payload",p},{"sha256",QString::fromLatin1(underlay::digest(json(p)).toHex())}}));}
